package dev.eugheist.tc4modern;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import thaumcraft.api.aspects.Aspect;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class WispAudit {
 static final BlockPos BASE=new BlockPos(800,121,-90);static int ticks;static volatile String failed;static Wisp attacker,roamer;static net.minecraft.world.entity.animal.Cow target;static Vec3 start;
 static void check(boolean ok,String msg){if(!ok)failed=msg;System.out.println("TC4_WISP "+(ok?"PASS ":"FAIL ")+msg);if(!ok)throw new IllegalStateException(msg);}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.wispAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();
 if(ticks==40)server.execute(()->{var p=server.getPlayerList().getPlayer(id);var l=server.overworld();p.teleportTo(l,BASE.getX()+.5,BASE.getY()+1,BASE.getZ()-7,0,0);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();l.setDayTime(6000);l.getEntitiesOfClass(Entity.class,new AABB(BASE).inflate(40),e->!(e instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);for(int x=-16;x<=16;x++)for(int z=-3;z<=25;z++)for(int y=-1;y<12;y++)l.setBlock(BASE.offset(x,y,z),(y==-1?Blocks.STONE:Blocks.AIR).defaultBlockState(),3);
 int i=0;for(var a:Aspect.getPrimalAspects()){var w=WispContent.WISP.get().create(l);w.moveTo(BASE.getX()-10+i++*4,BASE.getY()+2,BASE.getZ()+3,0,0);w.aspect(a);w.setNoAi(true);l.addFreshEntity(w);}
 attacker=WispContent.WISP.get().create(l);attacker.moveTo(BASE.getX()-4,BASE.getY()+2,BASE.getZ()+10,0,0);attacker.aspect(Aspect.FIRE);l.addFreshEntity(attacker);target=EntityType.COW.create(l);target.moveTo(attacker.getX()+4,BASE.getY(),attacker.getZ(),0,0);target.setNoAi(true);l.addFreshEntity(target);attacker.hurt(attacker.damageSources().mobAttack(target),1);check(attacker.getTarget()==target&&attacker.aggroCooldown==200,"retaliation selects attacker for 200 ticks");check(attacker.getMaxHealth()==22&&attacker.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)==3,"original health and damage");attacker.waypointX=attacker.getX();attacker.waypointY=attacker.getY();attacker.waypointZ=attacker.getZ()+2;attacker.courseChangeCooldown=10000;
 roamer=WispContent.WISP.get().create(l);roamer.moveTo(BASE.getX()+8,BASE.getY()+3,BASE.getZ()+14,0,0);l.addFreshEntity(roamer);roamer.waypointX=roamer.getX()+4;roamer.waypointY=roamer.getY();roamer.waypointZ=roamer.getZ();start=roamer.position();check(roamer.traversable(start.add(4,0,0)),"flight route with ground support is allowed");check(!roamer.traversable(start.add(0,20,0)),"flight route more than ten blocks above ground is refused");l.setBlock(BASE.offset(10,3,14),Blocks.STONE.defaultBlockState(),3);check(!roamer.traversable(start.add(4,0,0)),"solid obstacle blocks flight route");l.setBlock(BASE.offset(10,3,14),Blocks.AIR.defaultBlockState(),3);
 });
 if(ticks==110)LiquidDeathAudit.shot(mc,"wisp-primal-family.png");
 if(ticks==170)server.execute(()->{check(target.getHealth()<target.getMaxHealth(),"natural charged zap damages stationary target");check(attacker.getEntityData().get(Wisp.ZAP_SERIAL)>0,"zap synchronizes target and serial");check(roamer.aspect()!=null&&roamer.position().distanceToSqr(start)>.1,"roaming flight and random aspect selection");var l=server.overworld();var tag=new net.minecraft.nbt.CompoundTag();attacker.saveWithoutId(tag);var copy=WispContent.WISP.get().create(l);copy.load(tag);check(copy.aspect()==Aspect.FIRE,"aspect survives save/load");check(ScanTarget.entity(copy).aspects().equals(java.util.Map.of("ignis",2,"praecantatio",1,"aer",1)),"scanner reads aspect-specific original tags");attacker.hurt(attacker.damageSources().genericKill(),1000);var drops=l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,attacker.getBoundingBox().inflate(2));check(drops.stream().anyMatch(e->{var aspects=EssentiaItems.getAspects(e.getItem());return e.getItem().is(BasicsContent.WISP_ESSENCE.get())&&aspects!=null&&aspects.getAmount(Aspect.FIRE)==2;}),"death drops two units of its own aspect essence");var p=server.getPlayerList().getPlayer(id);p.getInventory().clearContent();var egg=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(AlchemyContent.id("wisp_spawn_egg"));p.getInventory().setItem(0,new net.minecraft.world.item.ItemStack(egg));p.containerMenu.broadcastChanges();var dropped=new net.minecraft.world.entity.item.ItemEntity(l,p.getX(),p.getY()+.5,p.getZ()+2,p.getMainHandItem().copy());dropped.setNoGravity(true);dropped.setNeverPickUp();dropped.setDeltaMovement(Vec3.ZERO);l.addFreshEntity(dropped);});
 if(ticks==190)LiquidDeathAudit.shot(mc,"wisp-egg-hand.png");if(ticks==200)mc.setScreen(new net.minecraft.client.gui.screens.inventory.InventoryScreen(mc.player));if(ticks==210){LiquidDeathAudit.shot(mc,"wisp-egg-inventory.png");mc.setScreen(null);}if(ticks==220)mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_FRONT);if(ticks==230)LiquidDeathAudit.shot(mc,"wisp-egg-third.png");if(ticks==240){mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);check(WispClient.rendered>0,"wisp renderer used");System.out.println(failed==null?"TC4_WISP ALL PASS":"TC4_WISP FAILED "+failed);mc.stop();}
 }
}
